def extract_function_bodies(node, valid_nodes):
        collected = []
        cursor = node.walk()
        visited = set()
        stack = [cursor.node]
        while stack:
            current = stack.pop()
            if current.id in visited:
                continue
            visited.add(current.id)
            parent_type = current.parent.type if current.parent else ""
            if current.type in valid_nodes and parent_type not in valid_nodes:
                collected.append(current)
            else:
                stack.extend(current.children)
