        if current_tokens + est_tokens > max_tokens and current_chunk:
            header = f"// FILE: {rel_path}\n// CHUNK {chunk_id} | estimated_tokens: {current_tokens} | starts at line {current_line}\n\n"
            chunks.append(header + '\n'.join(current_chunk))
