def write_chunks(chunks, out_dir, rel_path, verbose=False):
    module_path = group_output_by_module(rel_path)
    jsonl_path = out_dir / module_path / f"{Path(rel_path).stem}.jsonl"
    jsonl_path.parent.mkdir(parents=True, exist_ok=True)

    with open(jsonl_path, 'w', encoding='utf-8') as f:
        for i, chunk in enumerate(chunks):
