def chunk_folder(source_dir, out_dir, cache_dir, include_path=None, exclude_path=None, max_lines=80, max_tokens=None, force=False, verbose=False, extensions=None):
    source_path = Path(source_dir).resolve()
    out_path = Path(out_dir).resolve()
    cache_path = Path(cache_dir).resolve()
    allowed_exts = set(extensions or ['.cpp', '.hpp', '.h', '.cc', '.cxx', '.c', '.py', '.java', '.js', '.mjs'])
    if allowed_exts == {'all'}:
        allowed_exts = {'*'}

    print(f"Scanning: {source_path}")
    count = 0

    for file in source_path.rglob("*"):
        if file.is_file() and is_code_file(file, allowed_exts):
            file_str = str(file)
            if include_path and include_path not in file_str:
                if verbose:
                    print(f"[Skip] Not in include path: {file_str}")
                continue
            if exclude_path and exclude_path in file_str:
                if verbose:
                    print(f"[Skip] Matched exclude path: {file_str}")
                continue

            rel_path = file.relative_to(source_path)
            hash_file_path = cache_path / f"{rel_path}.hash"
            code_hash = hash_file(file)
            if not force and hash_file_path.exists() and hash_file_path.read_text() == code_hash:
                if verbose:
                    print(f"[Skip] Unchanged: {rel_path}")
                continue

            if verbose:
                print(f"[Chunk] {rel_path}")

            code = read_file(file)
            if max_tokens:
                try:
                    chunks = chunk_code_by_syntax(code, max_tokens=max_tokens, rel_path=rel_path, verbose=verbose)
                except Exception as e:
                    if verbose:
                        print(f"[Syntax Fallback] {rel_path}: {e}")
                    chunks = chunk_code_by_tokens(code, max_tokens=max_tokens, rel_path=rel_path, verbose=verbose)
            else:
                chunks = chunk_code_by_lines(code, max_lines=max_lines)

            write_chunks(chunks, out_path, rel_path, verbose=verbose)
            hash_file_path.parent.mkdir(parents=True, exist_ok=True)
            hash_file_path.write_text(code_hash)
            count += 1

    print(f"Chunking complete. Processed {count} files.")
def main():
    parser = argparse.ArgumentParser(
        description='DeepSeek Code Chunker and Prompt Tool. Use --max-lines or --max-tokens to set chunk size.'
    )
    subparsers = parser.add_subparsers(dest='command')

    chunk_parser = subparsers.add_parser('chunk')
    chunk_parser.add_argument('--mode', choices=['static', 'dynamic'], required=True)
    chunk_parser.add_argument('--source', required=True)
    chunk_parser.add_argument('--include', help='Restrict chunking to a subfolder')
    chunk_parser.add_argument('--exclude', help='Exclude chunking of a subfolder')
    chunk_parser.add_argument('--max-lines', type=int, default=80, help='Maximum number of lines per chunk')
    chunk_parser.add_argument('--max-tokens', type=int, help='Maximum number of estimated tokens per chunk')
    chunk_parser.add_argument('--force', action='store_true', help='Force re-chunking even if files are unchanged')
    chunk_parser.add_argument('--verbose', action='store_true', help='Enable detailed output')
    chunk_parser.add_argument('--ext', nargs='+', help='List of file extensions to include (e.g., .cpp .py .java) or "all"')

    args = parser.parse_args()

    if args.command == 'chunk':
        exts = args.ext or ['.cpp', '.hpp', '.h', '.cc', '.cxx', '.c','.py', '.java', '.js', '.mjs','hxx']
        chunk_folder(
            args.source,
            'chunks/static' if args.mode == 'static' else 'chunks/dynamic',
            'cache/static' if args.mode == 'static' else 'cache/dynamic',
            args.include,
            args.exclude,
            args.max_lines,
            args.max_tokens,
            True,  # force always True
            args.verbose,
            exts
        )
